import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";

const WorkerSplash = ({ onComplete }) => {
  const [phase, setPhase] = useState("cold"); // cold -> heat -> exit

  useEffect(() => {
    const heatTimer = setTimeout(() => setPhase("heat"), 1000);
    const exitTimer = setTimeout(() => setPhase("exit"), 3000);
    const completeTimer = setTimeout(onComplete, 3800);

    return () => {
      clearTimeout(heatTimer);
      clearTimeout(exitTimer);
      clearTimeout(completeTimer);
    };
  }, [onComplete]);

  return (
    <div className="h-screen w-full bg-[#FDFAD8] flex items-center justify-center relative overflow-hidden">

      {/* 1. THE TRUCK WIPE EXIT */}
      {phase === "exit" && <div className="animate-wipe" />}

      {/* 2. THE BACKGROUND DATA (Unconventional Grid) */}
      <div className="absolute inset-0 opacity-5 pointer-events-none">
        <div className="grid grid-cols-12 h-full">
          {[...Array(12)].map((_, i) => (
            <div key={i} className="border-r border-[#47510B] h-full" />
          ))}
        </div>
      </div>

      {/* 3. THE CORE UNIT */}
      <div className="flex flex-col items-center z-10">
        <div className="flex items-center gap-0">

          {/* T1 - Slides in from the top left */}
          <motion.h1 
            initial={{ x: -100, y: -100, opacity: 0 }}
            animate={{ x: 0, y: 0, opacity: 1 }}
            className={`text-[12rem] md:text-[16rem] font-[1000] italic leading-none tracking-tighter
              ${phase === "heat" ? "animate-thermal" : "text-[#47510B]"}
            `}
          >
            T
          </motion.h1>

          {/* THE 2 - The "High-Voltage" Center */}
          <motion.div 
            initial={{ scale: 0, rotate: -90 }}
            animate={{ scale: 1.2, rotate: 12 }}
            transition={{ type: "spring", stiffness: 200, delay: 0.5 }}
            className="bg-[#47510B] p-4 border-[12px] border-[#CAD23C] shadow-[15px_15px_0px_#FF5B03]"
          >
            <span className="text-white text-9xl font-[1000] italic">2</span>
          </motion.div>

          {/* T2 - Slides in from the bottom right */}
          <motion.h1 
            initial={{ x: 100, y: 100, opacity: 0 }}
            animate={{ x: 0, y: 0, opacity: 1 }}
            className={`text-[12rem] md:text-[16rem] font-[1000] italic leading-none tracking-tighter
              ${phase === "heat" ? "animate-thermal" : "text-[#47510B]"}
            `}
          >
            T
          </motion.h1>
        </div>

        {/* 4. THE TACTICAL BAR (Unconventional Loading) */}
        <div className="mt-20 flex items-center gap-6">
          <div className="h-1 w-24 bg-[#47510B] rounded-full overflow-hidden">
            <motion.div 
              initial={{ x: "-100%" }}
              animate={{ x: "100%" }}
              transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
              className="h-full w-1/2 bg-[#FF5B03]"
            />
          </div>

          <h2 className="text-[#47510B] font-black text-2xl tracking-[0.4em] uppercase">
            Worker
          </h2>

          <div className="h-1 w-24 bg-[#47510B] rounded-full overflow-hidden">
            <motion.div 
              initial={{ x: "100%" }}
              animate={{ x: "-100%" }}
              transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
              className="h-full w-1/2 bg-[#CAD23C]"
            />
          </div>
        </div>
      </div>

      {/* 5. MECHANICAL SPECS (Bottom Text) */}
      <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex gap-12 text-[10px] font-bold text-[#47510B] opacity-30">
        <span>ENGINE_TEMP: OPTIMAL</span>
        <span>LOAD_WEIGHT: 0.00kg</span>
        <span>GEAR: NEUTRAL</span>
      </div>
    </div>
  );
};

export default WorkerSplash;
